  added_n: { en: "{n} quote(s) added", ro: "{n} ofertă(e) adăugată(e)", ru: "Добавлено расчётов: {n}", uk: "Додано розрахунків: {n}" },
  or_pick: { en: "Or pick one quote", ro: "Sau alege o ofertă", ru: "Или выберите один расчёт", uk: "Або оберіть один розрахунок" },
  no_quotes_market: { en: "There is no quote in Moldova or Ukraine yet. Make a quote first, then come back to group it.", ro: "Încă nu există nicio ofertă pentru Moldova sau Ucraina. Fă mai întâi o ofertă, apoi revino să o grupezi.", ru: "Расчётов по Молдове или Украине пока нет. Сначала сделайте расчёт, затем вернитесь, чтобы сгруппировать.", uk: "Розрахунків по Молдові чи Україні поки немає. Спершу зробіть розрахунок, потім поверніться, щоб згрупувати." },
